"use client"

/**
 * niko-table — created by Semir N. (Semkoo, https://github.com/Semkoo) with AI assistance.
 *
 * Before reporting anything: please check the changelog first.
 *  - In-repo: ./CHANGELOG.md
 *  - Docs site: https://niko-table.com/changelog
 *
 * Found a bug or have a fix? Open an issue or PR on GitHub so other
 * users (and future LLMs reading this code) benefit:
 * https://github.com/Semkoo/niko-table-registry
 */
import type { RowData } from "@tanstack/react-table"
import React from "react"

import {
  TableColumnSortOptions,
  TableColumnSortMenu,
} from "../filters/table-column-sort"
import { useDataTable } from "../core/data-table-context"
import { useColumnHeaderContext } from "./data-table-column-header"
import { Kbd } from "@/components/ui/kbd"
import { cn } from "@/lib/utils"

/**
 * Sorting options for column header menu using context.
 */
export function DataTableColumnSortOptions<TData extends RowData, TValue>(
  props: Omit<
    React.ComponentProps<typeof TableColumnSortOptions>,
    "column" | "table"
  >,
) {
  const { column } = useColumnHeaderContext<TData, TValue>(true)
  const { table } = useDataTable<TData>()
  return <TableColumnSortOptions column={column} table={table} {...props} />
}

DataTableColumnSortOptions.displayName = "DataTableColumnSortOptions"

/**
 * Sorting menu for column header using context.
 *
 * Standalone button variant for inline use outside dropdown menus.
 */
export function DataTableColumnSortMenu<TData extends RowData, TValue>(
  props: Omit<
    React.ComponentProps<typeof TableColumnSortMenu>,
    "column" | "table"
  >,
) {
  const { column } = useColumnHeaderContext<TData, TValue>(true)
  const { table } = useDataTable<TData>()
  return <TableColumnSortMenu column={column} table={table} {...props} />
}

DataTableColumnSortMenu.displayName = "DataTableColumnSortMenu"

/**
 * One-line hint that Shift + click on a column's sort adds it to the current
 * sort. Place it in a toolbar; renders nothing when multi-sort is off
 * (`enableMultiSort: false`).
 */
export function DataTableSortHint<TData extends RowData>({
  className,
  ...props
}: React.ComponentProps<"p">) {
  const { table } = useDataTable<TData>()
  if (table.options.enableMultiSort === false) return null
  return (
    <p className={cn("text-sm text-muted-foreground", className)} {...props}>
      Hold <Kbd>Shift</Kbd> and click a column&apos;s sort to sort by more than
      one column.
    </p>
  )
}

DataTableSortHint.displayName = "DataTableSortHint"

"use client"

/**
 * niko-table — created by Semir N. (Semkoo, https://github.com/Semkoo) with AI assistance.
 *
 * Before reporting anything: please check the changelog first.
 *  - In-repo: ./CHANGELOG.md
 *  - Docs site: https://niko-table.com/changelog
 *
 * Found a bug or have a fix? Open an issue or PR on GitHub so other
 * users (and future LLMs reading this code) benefit:
 * https://github.com/Semkoo/niko-table-registry
 */
import React from "react"
import type { RowData } from "@tanstack/react-table"
import { Check, CircleHelp } from "lucide-react"

import { Button } from "@/components/niko-table/primitives/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/niko-table/primitives/dropdown-menu"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/niko-table/primitives/tooltip"
import { cn } from "@/lib/utils"
import { useDataTable } from "../core/data-table-context"

import { SORT_ICONS, SORT_LABELS } from "../config/data-table"
import type { SortIconVariant } from "../config/data-table"
import { FILTER_VARIANTS } from "../lib/constants"
import type { FilterVariant } from "../lib/constants"

import type { DataTableColumn, DataTableInstance } from "../types"
/**
 * Sort options menu items for composition inside TableColumnActions.
 *
 * @example
 * ```tsx
 * <TableColumnActions>
 *   <TableColumnSortOptions column={column} />
 * </TableColumnActions>
 * ```
 */
export function TableColumnSortOptions<TData extends RowData, TValue>({
  column,
  table: propTable,
  variant: propVariant,
  withSeparator = true,
}: {
  column: DataTableColumn<TData, TValue>
  table?: DataTableInstance<TData>
  variant?: SortIconVariant
  /** Whether to render a separator before the options. @default true */
  withSeparator?: boolean
}) {
  const context = useDataTable<TData>()
  const table = propTable || context.table
  const sortState = column.getIsSorted()

  const variant: FilterVariant =
    propVariant || column.columnDef.meta?.variant || FILTER_VARIANTS.TEXT

  const icons = SORT_ICONS[variant] || SORT_ICONS[FILTER_VARIANTS.TEXT]
  const labels = SORT_LABELS[variant] || SORT_LABELS[FILTER_VARIANTS.TEXT]

  const sortIndex = column.getSortIndex()
  const isMultiSort = table && table.state.sorting.length > 1
  const showSortBadge = isMultiSort && sortIndex !== -1

  /**
   * Use a ref for immediate synchronous access to shift key state.
   * React state updates are batched and async, which can cause race conditions
   * when the dropdown closes - the keyup event might reset state before
   * handleSort reads it. A ref provides synchronous access.
   */
  const isShiftPressedRef = React.useRef(false)
  const [isShiftPressed, setIsShiftPressed] = React.useState(false)

  React.useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === "Shift") {
        const isDown = e.type === "keydown"
        isShiftPressedRef.current = isDown
        setIsShiftPressed(isDown)
      }
    }
    window.addEventListener("keydown", handleKey, { capture: true })
    window.addEventListener("keyup", handleKey, { capture: true })
    return () => {
      window.removeEventListener("keydown", handleKey, { capture: true })
      window.removeEventListener("keyup", handleKey, { capture: true })
    }
  }, [])

  const handleSort = (
    direction: "asc" | "desc" | false,
    // Only `shiftKey` is read: a click event, or a React Aria press event.
    e: { shiftKey: boolean },
  ) => {
    // Keyboard activation synthesizes a click whose `shiftKey` is false, so the
    // window-level ref is what carries Shift for Enter/Space; the event's own
    // flag covers a plain shift-click.
    const isMulti = isShiftPressedRef.current || isShiftPressed || e.shiftKey

    if (direction === false) {
      column.clearSorting()
    } else {
      const isDesc = direction === "desc"
      const canMultiSort = column.getCanMultiSort()

      /**
       * @see https://tanstack.com/table/v8/docs/guide/sorting#multi-sorting
       * When using toggleSorting explicitly, we must manually pass the multi-sort flag.
       */
      column.toggleSorting(isDesc, canMultiSort ? isMulti : false)
    }
  }

  return (
    <>
      {withSeparator && <DropdownMenuSeparator />}
      <DropdownMenuLabel className="flex items-center justify-between text-xs font-normal text-muted-foreground">
        <div className="flex items-center gap-2">
          <span>Column Sort</span>
          {showSortBadge && (
            <Tooltip>
              <TooltipTrigger asChild>
                <span className="flex size-4 cursor-help items-center justify-center rounded-full bg-primary text-[10px] font-medium text-primary-foreground">
                  {sortIndex + 1}
                </span>
              </TooltipTrigger>
              <TooltipContent side="right">
                Sort priority (order in which columns are sorted)
              </TooltipContent>
            </Tooltip>
          )}
        </div>
        <Tooltip>
          <TooltipTrigger asChild>
            <CircleHelp className="size-3.5 cursor-help" />
          </TooltipTrigger>
          <TooltipContent side="right">
            TIP: Hold &apos;shift&apos; key to enable multi sort
          </TooltipContent>
        </Tooltip>
      </DropdownMenuLabel>
      <DropdownMenuItem
        onClick={e => handleSort("asc", e)}
        className={cn(
          "flex items-center",
          sortState === "asc" && "bg-accent text-accent-foreground",
        )}
      >
        <icons.asc className="mr-2 size-4 text-muted-foreground/70" />
        <span className="flex-1">{labels.asc}</span>
        {sortState === "asc" && <Check className="ml-2 size-4" />}
      </DropdownMenuItem>
      <DropdownMenuItem
        onClick={e => handleSort("desc", e)}
        className={cn(
          "flex items-center",
          sortState === "desc" && "bg-accent text-accent-foreground",
        )}
      >
        <icons.desc className="mr-2 size-4 text-muted-foreground/70" />
        <span className="flex-1">{labels.desc}</span>
        {sortState === "desc" && <Check className="ml-2 size-4" />}
      </DropdownMenuItem>
      {sortState && (
        <DropdownMenuItem onClick={() => column.clearSorting()}>
          <icons.unsorted className="mr-2 size-4 text-muted-foreground/70" />
          Clear Sort
        </DropdownMenuItem>
      )}
    </>
  )
}

/**
 * Standalone dropdown menu for sorting.
 *
 * For composition inside TableColumnActions, use TableColumnSortOptions instead.
 *
 * @example
 * ```tsx
 * // Standalone
 * <TableColumnSortMenu column={column} table={table} />
 *
 * // Composed
 * <TableColumnActions>
 *   <TableColumnSortOptions column={column} />
 * </TableColumnActions>
 * ```
 */
export function TableColumnSortMenu<TData extends RowData, TValue>({
  column,
  table: propTable,
  variant: propVariant,
  className,
}: {
  column: DataTableColumn<TData, TValue>
  table?: DataTableInstance<TData>
  variant?: SortIconVariant
  className?: string
}) {
  const context = useDataTable<TData>()
  const table = propTable || context.table
  const canSort = column.getCanSort()
  const sortState = column.getIsSorted()

  const variant: FilterVariant =
    propVariant || column.columnDef.meta?.variant || FILTER_VARIANTS.TEXT

  const icons = SORT_ICONS[variant] || SORT_ICONS[FILTER_VARIANTS.TEXT]

  if (!canSort) return null

  const SortIcon =
    sortState === "asc"
      ? icons.asc
      : sortState === "desc"
        ? icons.desc
        : icons.unsorted

  const sortIndex = column.getSortIndex()
  const isMultiSort = table && table.state.sorting.length > 1
  const showSortBadge = isMultiSort && sortIndex !== -1

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          variant="ghost"
          size="icon"
          className={cn(
            "size-7 transition-opacity dark:text-muted-foreground",
            sortState && "text-primary",
            className,
          )}
        >
          <div className="relative flex items-center justify-center">
            <SortIcon className="size-4" />
            {showSortBadge && (
              <span className="absolute -top-1 -right-2 flex size-3 items-center justify-center rounded-full bg-primary text-[9px] text-primary-foreground">
                {sortIndex + 1}
              </span>
            )}
          </div>
          <span className="sr-only">Sort column</span>
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-48">
        <TableColumnSortOptions
          column={column}
          table={table}
          variant={variant}
          withSeparator={false}
        />
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

TableColumnSortOptions.displayName = "TableColumnSortOptions"
TableColumnSortMenu.displayName = "TableColumnSortMenu"

"use client"

/**
 * Niko Table's tooltip primitive, React Aria build. Radix-shaped API
 * (`TooltipProvider`, `Tooltip`, `TooltipTrigger asChild`, `TooltipContent
 * side`) on shadcn's React Aria `TooltipTrigger` (which makes the first child
 * focusable) and `Tooltip` popup.
 */
import * as React from "react"
import { mergeProps } from "react-aria"
import type { Placement } from "react-aria-components"

import {
  Tooltip as TooltipPopup,
  TooltipTrigger as TooltipRoot,
} from "@/components/ui/tooltip"

type Side = "top" | "right" | "bottom" | "left"
type Align = "start" | "center" | "end"

function toPlacement(side: Side, align: Align): Placement {
  if (align === "center") return side
  if (side === "top" || side === "bottom") return `${side} ${align}`
  return `${side} ${align === "start" ? "top" : "bottom"}`
}

// React Aria has no provider: the provider's delay feeds each shadcn
// TooltipTrigger's own `delay` prop.
const TooltipDelayContext = React.createContext<number | undefined>(undefined)

/** Radix-shaped provider; it only carries the delay (Radix or Base UI name). */
function TooltipProvider({
  delayDuration,
  delay,
  children,
}: {
  /** Radix name. */
  delayDuration?: number
  /** Base UI name; accepted so a spread of both typechecks. */
  delay?: number
  children?: React.ReactNode
}) {
  return (
    <TooltipDelayContext.Provider value={delayDuration ?? delay}>
      {children}
    </TooltipDelayContext.Provider>
  )
}

function Tooltip({
  open,
  defaultOpen,
  onOpenChange,
  delayDuration,
  children,
}: {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  delayDuration?: number
  children?: React.ReactNode
}) {
  const providerDelay = React.useContext(TooltipDelayContext)
  return (
    <TooltipRoot
      delay={delayDuration ?? providerDelay}
      closeDelay={0}
      isOpen={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
    >
      {children}
    </TooltipRoot>
  )
}

/** Slot: shadcn's TooltipTrigger passes its focus props and ref here. */
function TooltipTrigger({
  asChild = false,
  children,
  ...props
}: React.ComponentProps<"button"> & { asChild?: boolean }) {
  if (asChild && React.isValidElement<object>(children))
    return React.cloneElement(children, mergeProps(children.props, props))
  return (
    <button type="button" {...props}>
      {children}
    </button>
  )
}

function TooltipContent({
  side = "top",
  align = "center",
  sideOffset = 4,
  alignOffset = 0,
  className,
  children,
}: {
  side?: Side
  align?: Align
  sideOffset?: number
  alignOffset?: number
  className?: string
  children?: React.ReactNode
}) {
  return (
    <TooltipPopup
      placement={toPlacement(side, align)}
      offset={sideOffset}
      crossOffset={alignOffset}
      className={className}
    >
      {children}
    </TooltipPopup>
  )
}

export { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger }

"use client"

/**
 * Niko Table's dropdown-menu primitive, React Aria build. Radix-shaped API
 * (`DropdownMenuTrigger asChild`, `DropdownMenuContent align side`, items with
 * `onClick` / `disabled` / `variant`, submenus, radio groups) on top of
 * `react-aria-components` `MenuTrigger` / `Pressable` and the React Aria shadcn
 * dropdown-menu pieces (a React Aria `Menu` in a `Popover`).
 *
 * A React Aria menu is a collection: only items, labels, separators, groups
 * and submenus render inside it. Wrap any other content in
 * `DropdownMenuPanel`, which renders it as a non-focusable menu node.
 */
import * as React from "react"
import { mergeProps } from "react-aria"
import {
  Header,
  MenuTrigger,
  OverlayTriggerStateContext,
  Pressable,
  type Placement,
  type PressEvent,
} from "react-aria-components"

import {
  DropdownMenu as MenuPopover,
  DropdownMenuGroup,
  DropdownMenuItem as MenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuSub,
  DropdownMenuSubContent as SubmenuPopover,
  DropdownMenuSubTrigger as SubmenuItem,
} from "@/components/ui/dropdown-menu"

type Side = "top" | "right" | "bottom" | "left"
type Align = "start" | "center" | "end"
type PressableChild = React.ComponentProps<typeof Pressable>["children"]

function toPlacement(side: Side, align: Align): Placement {
  if (align === "center") return side
  if (side === "top" || side === "bottom") return `${side} ${align}`
  return `${side} ${align === "start" ? "top" : "bottom"}`
}

/** Plain text of a node tree, for React Aria's type-to-select. */
function textOf(node: React.ReactNode): string {
  if (typeof node === "string" || typeof node === "number") return String(node)
  if (Array.isArray(node)) return node.map(textOf).join("")
  if (React.isValidElement<{ children?: React.ReactNode }>(node))
    return textOf(node.props.children)
  return ""
}

function DropdownMenu({
  open,
  defaultOpen,
  onOpenChange,
  children,
}: {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Radix option; React Aria menus are always modal. */
  modal?: boolean
  children?: React.ReactNode
}) {
  return (
    <MenuTrigger
      isOpen={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
    >
      {children}
    </MenuTrigger>
  )
}

function DropdownMenuTrigger({
  asChild = false,
  children,
  ...props
}: React.ComponentProps<"button"> & { asChild?: boolean }) {
  const isOpen = React.useContext(OverlayTriggerStateContext)?.isOpen ?? false
  const state = { "data-state": isOpen ? "open" : "closed" }
  // Slot: MenuTrigger hands its press, keyboard and aria props to the child;
  // the trigger's own props merge onto it.
  const child =
    asChild && React.isValidElement<object>(children) ? (
      React.cloneElement(children, mergeProps(children.props, props, state))
    ) : (
      <button type="button" {...props} {...state}>
        {children}
      </button>
    )
  // A host element (a plain <button>, <a>) cannot take React Aria's press
  // itself, so Pressable gives it one. A component child (the Button
  // primitive, shadcn's Button) takes it directly; wrapping it too would
  // register the press twice.
  return typeof child.type === "string" ? (
    <Pressable>{child as PressableChild}</Pressable>
  ) : (
    child
  )
}

function DropdownMenuContent({
  align = "center",
  side = "bottom",
  sideOffset = 4,
  alignOffset = 0,
  className,
  children,
}: {
  align?: Align
  side?: Side
  sideOffset?: number
  alignOffset?: number
  className?: string
  children?: React.ReactNode
}) {
  return (
    <MenuPopover
      placement={toPlacement(side, align)}
      offset={sideOffset}
      crossOffset={alignOffset}
      className={className}
    >
      {children}
    </MenuPopover>
  )
}

interface DropdownMenuItemProps {
  /** Runs on pointer and keyboard activation; the press event carries `shiftKey`. */
  onClick?: (event: PressEvent) => void
  disabled?: boolean
  variant?: "default" | "destructive"
  inset?: boolean
  textValue?: string
  className?: string
  children?: React.ReactNode
}

function DropdownMenuItem({
  onClick,
  disabled,
  textValue,
  children,
  ...props
}: DropdownMenuItemProps) {
  return (
    <MenuItem
      {...props}
      onPress={onClick}
      isDisabled={disabled}
      textValue={textValue ?? textOf(children)}
    >
      {children}
    </MenuItem>
  )
}

function DropdownMenuSubTrigger({
  disabled,
  textValue,
  children,
  ...props
}: Omit<DropdownMenuItemProps, "onClick" | "variant">) {
  return (
    <SubmenuItem
      {...props}
      isDisabled={disabled}
      textValue={textValue ?? textOf(children)}
    >
      {children}
    </SubmenuItem>
  )
}

function DropdownMenuSubContent({
  sideOffset,
  alignOffset,
  className,
  children,
}: {
  className?: string
  children?: React.ReactNode
  sideOffset?: number
  alignOffset?: number
}) {
  return (
    <SubmenuPopover
      // Unset keeps the shadcn aria submenu defaults.
      {...(sideOffset === undefined ? {} : { offset: sideOffset })}
      {...(alignOffset === undefined ? {} : { crossOffset: alignOffset })}
      className={className}
    >
      {children}
    </SubmenuPopover>
  )
}

function DropdownMenuRadioGroup({
  value,
  onValueChange,
  children,
}: {
  value?: string
  onValueChange?: (value: string) => void
  children?: React.ReactNode
}) {
  return (
    <DropdownMenuGroup
      selectionMode="single"
      disallowEmptySelection
      selectedKeys={value === undefined ? [] : [value]}
      onSelectionChange={keys => {
        if (keys === "all") return
        const [key] = keys
        if (key !== undefined) onValueChange?.(String(key))
      }}
    >
      {children}
    </DropdownMenuGroup>
  )
}

function DropdownMenuRadioItem({
  value,
  disabled,
  textValue,
  children,
  ...props
}: Omit<DropdownMenuItemProps, "onClick" | "variant"> & { value: string }) {
  return (
    <MenuItem
      {...props}
      id={value}
      isDisabled={disabled}
      textValue={textValue ?? textOf(children)}
    >
      {children}
    </MenuItem>
  )
}

function stopMenuKeys(event: React.KeyboardEvent) {
  // Keep typing / arrows inside the panel's own controls; Escape still closes.
  if (event.key !== "Escape") event.stopPropagation()
}

function DropdownMenuPanel({ children }: { children: React.ReactNode }) {
  return (
    <Header
      role="presentation"
      onKeyDown={stopMenuKeys}
      onKeyUp={stopMenuKeys}
      // The menu moves focus to its first item when focus enters it.
      onFocus={event => event.stopPropagation()}
    >
      {children}
    </Header>
  )
}

export {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuPanel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
}

"use client"

/**
 * Niko Table's button primitive, React Aria build: shadcn's React Aria
 * `Button` behind the Radix `Button` API Niko Table calls it with (native
 * `<button>` props, `variant`, `size`, `asChild`).
 *
 * - `onClick` goes to React Aria's `onClick`, its alias of `onPress`: a real
 *   MouseEvent on click and a synthesized click for keyboard and screen-reader
 *   presses, so `stopPropagation()` / `shiftKey` keep working.
 * - `disabled` becomes `isDisabled`.
 * - Everything else (title, tabIndex, role, aria-*, key and mouse handlers) goes
 *   on the `<button>` through React Aria's `render`, as on a native button.
 *   React Aria's Button would drop those attributes and stop key events.
 *
 * Overlay triggers (`PopoverTrigger asChild` and the rest) hand their press to
 * this button, so an `asChild` trigger's child must be this Button (or
 * shadcn's), as with shadcn's own React Aria triggers.
 */
import * as React from "react"
import { mergeProps } from "react-aria"
import type { VariantProps } from "class-variance-authority"

import {
  Button as ButtonPrimitive,
  buttonVariants,
} from "@/components/ui/button"
import { cn } from "@/lib/utils"

type OnPressClick = React.ComponentProps<typeof ButtonPrimitive>["onClick"]

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  children,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }) {
  if (
    asChild &&
    React.isValidElement<React.HTMLAttributes<HTMLElement>>(children)
  ) {
    // Slot: the child element is the button (e.g. a link styled as one); its
    // own handlers and refs compose with the button's.
    return React.cloneElement(children, {
      ...mergeProps(children.props, { "data-slot": "button" }, props),
      className: cn(
        buttonVariants({ variant, size }),
        className,
        children.props.className,
      ),
    } as React.HTMLAttributes<HTMLElement>)
  }

  const { ref, id, type, slot, disabled, onClick, onMouseDown, ...native } =
    props
  return (
    <ButtonPrimitive
      ref={ref}
      id={id}
      type={type}
      slot={slot}
      variant={variant}
      size={size}
      className={className}
      isDisabled={disabled}
      onClick={onClick as OnPressClick}
      render={domProps => (
        <button
          {...mergeProps(domProps, native)}
          onMouseDown={event => {
            // React Aria's press handler stops every left mousedown; a native
            // button lets it bubble (the grid selects cells on mousedown).
            event.stopPropagation = () => {}
            domProps.onMouseDown?.(event)
            delete (event as Partial<typeof event>).stopPropagation
            onMouseDown?.(event)
          }}
        />
      )}
    >
      {children}
    </ButtonPrimitive>
  )
}

export { Button, buttonVariants }
